<script lang="ts">
	// @ts-expect-error — generated by Wails
	import { GetSelectedLanguage, GetLanguages } from '@wails/go/gui/App.js';
	import { installState } from '$lib/store.svelte';
	import ConfirmDialog from '$components/ConfirmDialog.svelte';
	import type { DiskInfo, ManualPartition, PartitionType } from '$lib/types';
	import { TYPE_ESP, TYPE_SYSTEM } from '$lib/types';
	import { FileSystemVfat } from '$lib/constants';
	import { t } from '$lib/i18n';
	import { glyph, STEP_ICONS } from '$lib/icons';

	const pageIcon = glyph(STEP_ICONS.confirmation);

	interface Language {
		code: string;
		name: string;
		locale: string;
	}

	let languages = $state<Language[]>([]);
	let selectedLanguageName = $state<string>('—');

	async function loadLanguageInfo(): Promise<void> {
		try {
			languages = await GetLanguages();
			const code = await GetSelectedLanguage();
			const lang = languages.find((l) => l.code === code);
			selectedLanguageName = lang?.name || code || '—';
		} catch {
			selectedLanguageName = '—';
		}
	}

	loadLanguageInfo();

	// The root filesystem the user chose (ext4 or btrfs). Falls back to the
	// default so the summary never shows an empty filesystem for the System row.
	const fileSystem = $derived(installState.fileSystem || 'ext4');

	// Format a MB value with a space as the thousands separator (e.g. 487875 -> "487 875").
	function formatSizeMB(value: number): string {
		return String(value).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
	}

	// Mountpoint a partition role maps to. ESP → /boot, System → /, Preserve →
	// none. Mirrors the backend's mount step (ESP at /mnt/boot, System at /).
	function partitionMount(type: PartitionType): string {
		if (type === TYPE_ESP) return '/boot';
		if (type === TYPE_SYSTEM) return '/';
		return '';
	}

	// Filesystem a partition row will be formatted with. ESP is always vfat, the
	// System row uses the user's chosen root filesystem, and Preserve keeps the
	// partition's existing filesystem untouched.
	function partitionFstype(part: ManualPartition): string {
		if (part.type === TYPE_ESP) return FileSystemVfat;
		if (part.type === TYPE_SYSTEM) return fileSystem;
		return part.existingFstype || '';
	}

	// Whether the manual layout has at least one designated (ESP or System) row.
	const hasDesignated = $derived.by(
		() => !!installState.manualLayout?.partitions.some((p) => p.type === TYPE_ESP || p.type === TYPE_SYSTEM),
	);
</script>

<div class="page-layout">
	<div class="page-info">
		<span class="nf-icon page-icon" aria-hidden="true">{pageIcon}</span>
		<h2>{t('page.confirmation.title')}</h2>
		<p>{t('page.confirmation.subtitle')}</p>
	</div>
	<div class="page-content">
		<div class="summary">
			<div class="summary-section">
				<h3 class="section-title">{t('page.confirmation.sectionLanguage')}</h3>
				<p class="section-value">{selectedLanguageName}</p>
			</div>

			<div class="summary-section">
				<h3 class="section-title">{t('page.confirmation.sectionUser')}</h3>
				<p class="section-value">
					{t('page.confirmation.username')}: <strong>{installState.username || '—'}</strong>
				</p>
				{#if installState.password}
					<p class="section-value">
						{t('page.confirmation.password')}: <strong>{'●'.repeat(installState.password.length)}</strong>
					</p>
				{/if}
			</div>

			<div class="summary-section">
				<h3 class="section-title">{t('page.confirmation.sectionDisk')}</h3>
				{#if installState.disk}
					<div class="disk-summary">
						<p class="section-value disk-name">
							{installState.disk.model || '—'} ({installState.disk.sizeFormatted} {t(installState.disk.rotational ? 'disk.hdd' : 'disk.ssd')} {installState.disk.trans?.toUpperCase() || ''})
						</p>
						<p class="disk-path">{t('page.installation.target')}: <code>{installState.disk.path}</code></p>
						{#if installState.disk.fstype}
							<p class="disk-extra">{t('page.diskSelection.currentFileSystem')}: <span class="tag fstype-tag">{installState.disk.fstype}</span></p>
						{/if}

						{#if installState.manualMode}
							<!-- Manual mode: show the partition plan the user designed -->
							{#if installState.manualLayout && hasDesignated}
								<div class="plan-table">
									<div class="plan-head">
										<span class="plan-col-name">{t('disk.name')}</span>
										<span class="plan-col-size">{t('disk.sizeMB')}</span>
										<span class="plan-col-role">{t('manual.typeCol')}</span>
										<span class="plan-col-mount">{t('page.confirmation.mount')}</span>
										<span class="plan-col-fs">{t('page.confirmation.filesystem')}</span>
									</div>
									{#each installState.manualLayout.partitions as part (part.index)}
										<div class="plan-row" class:designated={part.type === TYPE_ESP || part.type === TYPE_SYSTEM}>
											<span class="plan-col-name">
												{#if part.path}
													{part.path}
												{:else}
													<span class="part-new">{t('manual.newPart')}</span>
												{/if}
											</span>
											<span class="plan-col-size">{formatSizeMB(part.sizeMB)}</span>
											<span class="plan-col-role">
												<span class="tag role-tag {part.type}">{t('manual.type.' + (part.type || 'preserve'))}</span>
											</span>
											<span class="plan-col-mount">{partitionMount(part.type) || '—'}</span>
											<span class="plan-col-fs">
												{#if partitionFstype(part)}
													<span class="tag fs-tag">{t('fs.' + partitionFstype(part))}</span>
												{:else}
													—
												{/if}
											</span>
										</div>
									{/each}
								</div>
							{:else}
								<p class="disk-extra">{t('manual.dualbootHint')}</p>
							{/if}
						{:else}
							<p class="disk-extra">
								{t('page.diskSelection.selectedFileSystem')}: <span class="tag fs-tag">{installState.fileSystem || '—'}</span>
							</p>
						{/if}
						{#if installState.disk.serial}
							<p class="disk-extra">{t('validation.serial')}: <span class="tag serial-tag">{installState.disk.serial}</span></p>
						{/if}
					</div>
				{:else}
					<p class="section-value error">No disk selected</p>
				{/if}
			</div>
		</div>
	</div>
</div>

	<!-- Installation confirmation (mode-aware copy: wipe vs. dualboot-safe) -->
	<ConfirmDialog bind:show={installState.showConfirmDialog} />

